#![cfg(feature = "tls")]
//! TLS (feature `tls`): a rustls-terminated listener in front of `FakeWarp10`
//! with a throw-away certificate generated by the `openssl` CLI (the tests are
//! skipped with a notice when it is missing). The sink trusts it through
//! `Warp10Config::tls_extra_roots_der`.

use futures_rustls::{
    TlsAcceptor,
    rustls::{
        ServerConfig,
        crypto::ring,
        pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer},
    },
};
use moonpool_core::TokioProviders;
use std::{path::PathBuf, process::Command, sync::Arc, time::Duration};
use streaming_core::{Emit, EmitId, NodeId, Origin, Position, SinkConnector, SliceId, datum};
use streaming_warp10::{
    Gts, GtsValue, Warp10Config, Warp10Writer,
    fake::{FakeWarp10, PointKey},
};
use tokio::net::TcpListener;
use tokio_util::compat::TokioAsyncReadCompatExt;

struct Cert {
    cert_der: Vec<u8>,
    key_der: Vec<u8>,
}

fn generate_cert(tag: &str) -> Option<Cert> {
    let dir: PathBuf = std::env::temp_dir().join(format!("warp10-tls-{}-{tag}", std::process::id()));
    std::fs::create_dir_all(&dir).ok()?;
    let p = |n: &str| dir.join(n).to_string_lossy().into_owned();
    let run = |args: &[&str]| {
        Command::new("openssl")
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
    };
    run(&[
        "req",
        "-x509",
        "-newkey",
        "ec",
        "-pkeyopt",
        "ec_paramgen_curve:prime256v1",
        "-nodes",
        "-keyout",
        &p("key.pem"),
        "-out",
        &p("cert.pem"),
        "-days",
        "2",
        "-subj",
        "/CN=localhost",
        "-addext",
        "subjectAltName=DNS:localhost",
        "-addext",
        "basicConstraints=critical,CA:FALSE",
    ])?;
    run(&["x509", "-in", &p("cert.pem"), "-outform", "DER", "-out", &p("cert.der")])?;
    run(&[
        "pkcs8",
        "-topk8",
        "-nocrypt",
        "-in",
        &p("key.pem"),
        "-outform",
        "DER",
        "-out",
        &p("key.der"),
    ])?;
    let cert = Cert {
        cert_der: std::fs::read(p("cert.der")).ok()?,
        key_der: std::fs::read(p("key.der")).ok()?,
    };
    let _ = std::fs::remove_dir_all(&dir);
    Some(cert)
}

async fn start_tls_fake(fake: FakeWarp10, cert: &Cert) -> u16 {
    let config = ServerConfig::builder_with_provider(Arc::new(ring::default_provider()))
        .with_safe_default_protocol_versions()
        .unwrap()
        .with_no_client_auth()
        .with_single_cert(
            vec![CertificateDer::from(cert.cert_der.clone())],
            PrivateKeyDer::from(PrivatePkcs8KeyDer::from(cert.key_der.clone())),
        )
        .unwrap();
    let acceptor = TlsAcceptor::from(Arc::new(config));
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    tokio::spawn(async move {
        loop {
            let Ok((sock, _)) = listener.accept().await else {
                return;
            };
            let (acceptor, fake) = (acceptor.clone(), fake.clone());
            tokio::spawn(async move {
                if let Ok(stream) = acceptor.accept(sock.compat()).await {
                    fake.serve_stream(stream).await;
                }
            });
        }
    });
    port
}

fn emit(n: u64, gts: Gts) -> Emit {
    let origin = Origin::source(Position(0, n, 0));
    let slice = SliceId::Source {
        node: NodeId::new("n").unwrap(),
        partition: 0,
    };
    Emit {
        id: EmitId::new(&slice, &origin),
        origin,
        ts: 0,
        key: None,
        value: datum(gts),
    }
}

fn sink(host: &str, port: u16, roots: Vec<Vec<u8>>) -> Warp10Writer<TokioProviders> {
    let mut config = Warp10Config::new(&format!("https://{host}:{port}/api/v0/update"), "tok").unwrap();
    config.tls_extra_roots_der = roots;
    config.timeout = Duration::from_secs(5);
    Warp10Writer::new(TokioProviders::new(), config).unwrap()
}

#[tokio::test]
async fn write_over_tls_and_retry_after_a_failure() {
    let Some(cert) = generate_cert("ok") else {
        eprintln!("NOTICE: openssl CLI unavailable or failed, skipping TLS test");
        return;
    };
    let fake = FakeWarp10::new("tok");
    let port = start_tls_fake(fake.clone(), &cert).await;
    let sink = sink("localhost", port, vec![cert.cert_der.clone()]);
    let batch = vec![
        emit(0, Gts::new("tls.m").label("k", "v").at(1).value(7)),
        emit(1, Gts::new("tls.m").label("k", "v").at(2).value("é")),
    ];
    sink.write(&batch).await.expect("write over TLS");
    assert_eq!(fake.len(), 2);

    fake.fail_next(1, 503);
    assert!(sink.write(&batch).await.unwrap_err().0.contains("503"));
    sink.write(&batch).await.unwrap();
    assert_eq!(
        fake.get(&PointKey::new("tls.m", [("k", "v")], 1000)),
        Some(GtsValue::Long(7))
    );
    assert_eq!(fake.len(), 2);
}

#[tokio::test]
async fn untrusted_or_mismatched_certificates_are_refused() {
    let Some(cert) = generate_cert("refuse") else {
        eprintln!("NOTICE: openssl CLI unavailable or failed, skipping TLS test");
        return;
    };
    let fake = FakeWarp10::new("tok");
    let port = start_tls_fake(fake.clone(), &cert).await;
    let batch = vec![emit(0, Gts::new("tls.m").at(1).value(1))];

    // Unknown issuer: not in the web PKI roots and not added.
    let err = sink("localhost", port, vec![]).write(&batch).await.unwrap_err();
    assert!(err.0.contains("TLS handshake"), "{err}");

    // Trusted certificate, wrong host name (it is issued for `localhost`).
    let err = sink("127.0.0.1", port, vec![cert.cert_der.clone()])
        .write(&batch)
        .await
        .unwrap_err();
    assert!(err.0.contains("TLS handshake"), "{err}");
    assert!(fake.is_empty());
}

#[tokio::test]
async fn plain_http_against_a_tls_port_fails_instead_of_hanging() {
    let Some(cert) = generate_cert("plain") else {
        eprintln!("NOTICE: openssl CLI unavailable or failed, skipping TLS test");
        return;
    };
    let fake = FakeWarp10::new("tok");
    let port = start_tls_fake(fake.clone(), &cert).await;
    let mut config = Warp10Config::new(&format!("http://127.0.0.1:{port}/api/v0/update"), "tok").unwrap();
    config.timeout = Duration::from_millis(500);
    let plain = Warp10Writer::new(TokioProviders::new(), config).unwrap();
    assert!(plain.write(&[emit(0, Gts::new("m").at(1).value(1))]).await.is_err());
    assert!(fake.is_empty());
}
